export function addDays(value: IsoTimestamp, days: number): IsoTimestamp {
  return toIsoTimestamp(new Date(parseIso(value).getTime() + days * DAY_MS));
}

/**
 * Adds calendar months in UTC, keeping the time of day.
 *
 * When the target month has no such day, the result is that month's last day
 * (31 January → 28 February). The clamped day is what the next call sees, so
 * 28 February continues to 28 March rather than jumping back to the 31st.
 * Twelve months is one year, which also maps 29 February onto 28 February.
 */
export function addCalendarMonths(value: Date, months: number): Date {
  const monthIndex = value.getUTCMonth() + months;
  const year = value.getUTCFullYear() + Math.floor(monthIndex / 12);
  const month = ((monthIndex % 12) + 12) % 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const day = Math.min(value.getUTCDate(), lastDay);

  return new Date(
    Date.UTC(
      year,
      month,
      day,
      value.getUTCHours(),
      value.getUTCMinutes(),
      value.getUTCSeconds(),
      value.getUTCMilliseconds(),
    ),
  );
}

