import { and, eq, isNotNull, isNull, lte, ne } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, invoices, organizations, subscriptions } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toInvoice, toSubscription } from "./_mappers";
import type { BillingInterval, Invoice, PlanId, Subscription } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

/** Every live workspace's subscription. Archived workspaces are omitted. */
export async function listSubscriptionsForBilling(): Promise<
  readonly Subscription[]
> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(isNull(organizations.archivedAt))
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

/** Replaces the current period without touching plan, seats or status. */
export async function setCurrentPeriod(
  orgId: OrgId,
  currentPeriodStart: IsoTimestamp,
  currentPeriodEnd: IsoTimestamp,
): Promise<Subscription> {
  const row = getDb()
    .update(subscriptions)
    .set({
      currentPeriodStart,
      currentPeriodEnd,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(orgPredicate(subscriptions.orgId, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Subscription for org ${orgId} not found`);
  return toSubscription(row);
}

export type PeriodInvoiceDraft = {
  number: string;
  amountCents: number;
  periodStart: IsoTimestamp;
  periodEnd: IsoTimestamp;
};

/**
 * Moves an active period forward only when it still ends at `expectedPeriodEnd`,
 * and writes the period's invoice in the same transaction. A second caller
 * sees the period already moved and gets `null` instead of another invoice.
 */
export async function commitRenewedPeriod(
  orgId: OrgId,
  expectedPeriodEnd: IsoTimestamp,
  nextPeriodEnd: IsoTimestamp,
  invoice: PeriodInvoiceDraft | null,
): Promise<{ subscription: Subscription; invoice: Invoice | null } | null> {
  return getDb().transaction((tx) => {
    const stamp = toIsoTimestamp(new Date());
    const row = tx
      .update(subscriptions)
      .set({
        currentPeriodStart: expectedPeriodEnd,
        currentPeriodEnd: nextPeriodEnd,
        updatedAt: stamp,
      })
      .where(
        and(
          orgPredicate(subscriptions.orgId, orgId),
          eq(subscriptions.status, "active"),
          eq(subscriptions.currentPeriodEnd, expectedPeriodEnd),
        ),
      )
      .returning()
      .get();

    if (!row) return null;

    if (!invoice) {
      return { subscription: toSubscription(row), invoice: null };
    }

    const created = tx
      .insert(invoices)
      .values({
        id: newId(),
        orgId,
        number: invoice.number,
        amountCents: invoice.amountCents,
        currency: "usd",
        periodStart: invoice.periodStart,
        periodEnd: invoice.periodEnd,
        paidAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    return { subscription: toSubscription(row), invoice: toInvoice(created) };
  });
}

/**
 * Ends a cancellation that is still pending at `expectedCancelAt`: free plan,
 * active, nothing pending, monthly period starting on the cancellation date.
 * Returns null when that cancellation was already settled.
 */
export async function commitCancellationToFree(
  orgId: OrgId,
  expectedCancelAt: IsoTimestamp,
  periodStart: IsoTimestamp,
  periodEnd: IsoTimestamp,
): Promise<Subscription | null> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .update(subscriptions)
    .set({
      plan: "free",
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: periodStart,
      currentPeriodEnd: periodEnd,
      updatedAt: stamp,
    })
    .where(
      and(
        orgPredicate(subscriptions.orgId, orgId),
        eq(subscriptions.status, "canceled"),
        eq(subscriptions.cancelAt, expectedCancelAt),
      ),
    )
    .returning()
    .get();

  return row ? toSubscription(row) : null;
}

/** Feeds the trial-expiry job; cross-tenant by design, it sweeps every org. */

