export async function nextInvoiceNumber(
  orgId: OrgId,
  when: Date,
): Promise<string> {
  const row = getDb()
    .select({ value: count() })
    .from(invoices)
    .where(orgPredicate(invoices.orgId, orgId))
    .get();
  const sequence = (row?.value ?? 0) + 1;
  return `INV-${when.getUTCFullYear()}-${String(sequence).padStart(4, "0")}`;
}

