function monthsInInterval(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

function fullPeriodCents(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return getPlanLimits(plan).priceCentsPerSeatMonthly * seats * monthsInInterval(interval);
}

/** Whole days in the period, rounded, and never zero. */
function daysInPeriod(start: IsoTimestamp, end: IsoTimestamp): number {
  const delta = parseIso(end).getTime() - parseIso(start).getTime();
  return Math.max(1, Math.round(delta / DAY_MS));
}

/**
 * Whole or started days from `now` until the period end. 14 days and 22 hours
 * count as 15. Once the end has been reached there are none.
 */
function daysRemaining(now: Date, end: IsoTimestamp): number {
  const delta = parseIso(end).getTime() - now.getTime();
  if (delta <= 0) return 0;
  return Math.ceil(delta / DAY_MS);
}

function prorateCents(
  fullCents: number,
  now: Date,
  start: IsoTimestamp,
  end: IsoTimestamp,
): number {
  if (fullCents <= 0) return 0;
  const left = daysRemaining(now, end);
  if (left === 0) return 0;
  return Math.floor((fullCents * left) / daysInPeriod(start, end));
}

function planChangeCharge(
  existing: Subscription,
  nextPlan: PlanId,
  nextInterval: BillingInterval,
  now: Date,
): { amountCents: number; periodStart: IsoTimestamp; periodEnd: IsoTimestamp; resetPeriod: boolean } {
  const unchanged = {
    amountCents: 0,
    periodStart: existing.currentPeriodStart,
    periodEnd: existing.currentPeriodEnd,
    resetPeriod: false,
  };

  if (existing.status === "trialing") return unchanged;

  if (existing.plan === "free" && nextPlan !== "free") {
    const months = monthsInInterval(nextInterval);
    const periodStart = toIsoTimestamp(now);
    const periodEnd = toIsoTimestamp(addCalendarMonths(now, months));
    return {
      amountCents: fullPeriodCents(nextPlan, existing.seats, nextInterval),
      periodStart,
      periodEnd,
      resetPeriod: true,
    };
  }

  if (existing.status === "active" && existing.plan !== "free" && nextPlan !== "free") {
    const difference =
      getPlanLimits(nextPlan).priceCentsPerSeatMonthly -
      getPlanLimits(existing.plan).priceCentsPerSeatMonthly;
    if (difference <= 0) return unchanged;

    return {
      amountCents: prorateCents(
        difference * existing.seats * monthsInInterval(existing.interval),
        now,
        existing.currentPeriodStart,
        existing.currentPeriodEnd,
      ),
      periodStart: existing.currentPeriodStart,
      periodEnd: existing.currentPeriodEnd,
      resetPeriod: false,
    };
  }

  return unchanged;
}

async function issueInvoice(input: {
  orgId: OrgId;
  amountCents: number;
  periodStart: IsoTimestamp;
  periodEnd: IsoTimestamp;
  actorId: UserId | null;
  occurredAt: IsoTimestamp;
  numberedAt: Date;
}): Promise<void> {
  if (input.amountCents <= 0) return;

  const invoice = await invoiceRepo.insertInvoice(input.orgId, {
    orgId: input.orgId,
    number: await invoiceRepo.nextInvoiceNumber(input.orgId, input.numberedAt),
    amountCents: input.amountCents,
    currency: "usd",
    periodStart: input.periodStart,
    periodEnd: input.periodEnd,
    paidAt: null,
  });

  await publishInvoice(invoice, {
    orgId: input.orgId,
    actorId: input.actorId,
    occurredAt: input.occurredAt,
  });
}

async function publishInvoice(
  invoice: Invoice,
  envelope: {
    orgId: OrgId;
    actorId: UserId | null;
    occurredAt: IsoTimestamp;
  },
): Promise<void> {
  const payload: TaskflowEventMap["billing.invoice_issued"] = {
    orgId: envelope.orgId,
    actorId: envelope.actorId,
    occurredAt: envelope.occurredAt,
    invoiceId: invoice.id,
    invoiceNumber: invoice.number,
    amountCents: invoice.amountCents,
    periodStart: invoice.periodStart,
    periodEnd: invoice.periodEnd,
  };

  await recordInvoiceEffects(payload);
  await emit("billing.invoice_issued", payload);
}

