{"type":"SearchReplace","EditsApplied":{"old_string":"/** Maps a quota dimension onto the counter that measures it. */","new_string":"/**
 * Renews one workspace's subscription as of `now`.
 *
 * Canceled subscriptions end on their cancellation date (free, active, a
 * monthly period from that date, one `billing.plan_changed`) and are not
 * touched before then. Active subscriptions gain one period per elapsed
 * interval until the period end is past `now`; each paid period is invoiced
 * in full. Trialing and past-due subscriptions are left alone. A second call
 * at the same instant finds nothing left to do.
 */
export async function advanceDueBilling(
  subscription: Subscription,
  now: Date,
): Promise<number> {
  if (subscription.status === "trialing" || subscription.status === "past_due") {
    return 0;
  }

  let current = subscription;
  let processed = 0;
  const occurredAt = toIsoTimestamp(now);

  if (current.status === "canceled") {
    if (
      current.cancelAt === null ||
      parseIso(current.cancelAt).getTime() > now.getTime()
    ) {
      return 0;
    }

    const periodStart = current.cancelAt;
    const periodEnd = toIsoTimestamp(addCalendarMonths(parseIso(periodStart), 1));
    const from = current.plan;
    const settled = await subscriptionRepo.commitCancellationToFree(
      current.orgId,
      current.cancelAt,
      periodStart,
      periodEnd,
    );
    if (!settled) return 0;

    await emit("billing.plan_changed", {
      orgId: current.orgId,
      actorId: null,
      occurredAt,
      from,
      to: "free",
    });

    current = settled;
    processed += 1;
  }

  if (current.status !== "active") return processed;

  let guard = 0;
  while (parseIso(current.currentPeriodEnd).getTime() <= now.getTime()) {
    if (++guard > 600) {
      throw new Error(`Billing period for ${current.orgId} did not advance`);
    }

    const periodStart = current.currentPeriodEnd;
    const months = monthsInInterval(current.interval);
    const periodEnd = toIsoTimestamp(
      addCalendarMonths(parseIso(periodStart), months),
    );
    const amountCents =
      current.plan === "free"
        ? 0
        : fullPeriodCents(current.plan, current.seats, current.interval);

    const committed = await subscriptionRepo.commitRenewedPeriod(
      current.orgId,
      periodStart,
      periodEnd,
      amountCents > 0
        ? {
            number: await invoiceRepo.nextInvoiceNumber(current.orgId, now),
            amountCents,
            periodStart,
            periodEnd,
          }
        : null,
    );
    if (!committed) break;

    if (committed.invoice) {
      await publishInvoice(committed.invoice, {
        orgId: current.orgId,
        actorId: null,
        occurredAt,
      });
    }

    current = committed.subscription;
    processed += 1;
  }

  return processed;
}

/**
 * Audit row plus the owner's notification for one invoice. Idempotent on
 * invoice id so a bus listener and the issuer cannot double-deliver.
