export async function recordInvoiceEffects(
  payload: TaskflowEventMap["billing.invoice_issued"],
): Promise<void> {
  if (announcedInvoices.has(payload.invoiceId)) return;
  announcedInvoices.add(payload.invoiceId);

  await record(payload.orgId, "billing.invoice_issued", {
    actorId: payload.actorId,
    subjectKind: "subscription",
    subjectId: payload.orgId,
    projectId: null,
    summary: `Issued invoice ${payload.invoiceNumber} for ${payload.amountCents} cents`,
    metadata: {
      invoiceId: payload.invoiceId,
      invoiceNumber: payload.invoiceNumber,
      amountCents: payload.amountCents,
    },
  });

  const org = await orgRepo.findOrgById(payload.orgId);
  if (!org || org.archivedAt !== null) return;

  await notify(payload.orgId, "invoice_issued", [org.ownerId], {
    title: "Invoice issued",
    body: `Invoice ${payload.invoiceNumber} for ${payload.amountCents} cents was issued.`,
    href: "/settings/billing",
    actorId: null,
  });
}

