const logger = createLogger("billing-renewal-job");

/**
 * Walks every live workspace. An active subscription whose period has ended
 * gains one new period per elapsed interval; each paid period is invoiced.
 * A canceled subscription ends on its cancellation date and not before.
 * Trialing and past-due subscriptions are left for the trial-expiry job.
 * Running again at the same instant changes nothing.
 */
export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listSubscriptionsForBilling();

    for (const subscription of subscriptions) {
      const org = await orgRepo.findOrgById(subscription.orgId);
      if (!org || org.archivedAt !== null) continue;

      try {
        result.processed += await advanceDueBilling(subscription, now);
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

