import type { IsoTimestamp, OrgId } from "@/types/common";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

function iso(date: Date): IsoTimestamp {
  return toIsoTimestamp(date);
}

async function shape(
  orgId: OrgId,
  patch: {
    plan?: "free" | "starter" | "growth" | "enterprise";
    interval?: BillingInterval;
    status?: SubscriptionStatus;
    seats?: number;
    currentPeriodStart?: IsoTimestamp;
    currentPeriodEnd?: IsoTimestamp;
    cancelAt?: IsoTimestamp | null;
  },
): Promise<void> {
  getDb()
    .update(subscriptions)
    .set(patch)
    .where(eq(subscriptions.orgId, orgId))
    .run();
}

describe("billing period arithmetic", () => {
  it("clamps short months and carries the clamped day forward", () => {
    const jan31 = new Date("2026-01-31T15:30:00.000Z");
    const feb = addCalendarMonths(jan31, 1);
    expect(feb.toISOString()).toBe("2026-02-28T15:30:00.000Z");
    expect(addCalendarMonths(feb, 1).toISOString()).toBe("2026-03-28T15:30:00.000Z");

    const leap = new Date("2024-01-31T00:00:00.000Z");
    expect(addCalendarMonths(leap, 1).toISOString()).toBe("2024-02-29T00:00:00.000Z");

    const feb29 = new Date("2024-02-29T08:15:00.000Z");
    const next = addCalendarMonths(feb29, 12);
    expect(next.toISOString()).toBe("2025-02-28T08:15:00.000Z");
    expect(addCalendarMonths(next, 12).toISOString()).toBe("2026-02-28T08:15:00.000Z");
  });
});

describe("billing renewal job", () => {
  it("renews each elapsed monthly period and invoices the seat count", async () => {
    const tenant = await createTenant("renew-monthly", "starter");
    await shape(tenant.org.id, {
      status: "active",
      seats: 2,
      interval: "monthly",
      currentPeriodStart: iso(new Date("2026-01-15T10:00:00.000Z")),
      currentPeriodEnd: iso(new Date("2026-02-15T10:00:00.000Z")),
      cancelAt: null,
    });

    const now = new Date("2026-04-15T09:00:00.000Z");
    const seen: string[] = [];
    const off = subscribe("billing.invoice_issued", (payload) => {
      seen.push(payload.invoiceNumber);
    });

    const result = await runBillingRenewalJob(now);
    off();

    expect(result.failed).toBe(0);
    expect(result.processed).toBe(2);
    expect(seen).toHaveLength(2);

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription?.currentPeriodStart).toBe("2026-03-15T10:00:00.000Z");
    expect(subscription?.currentPeriodEnd).toBe("2026-04-15T10:00:00.000Z");

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices.map((invoice) => invoice.amountCents)).toEqual([1800, 1800]);
    expect(invoices.map((invoice) => invoice.periodStart)).toEqual([
      "2026-03-15T10:00:00.000Z",
      "2026-02-15T10:00:00.000Z",
    ]);
    expect(invoices.every((invoice) => invoice.currency === "usd" && invoice.paidAt === null)).toBe(
      true,
    );
    expect(new Set(invoices.map((invoice) => invoice.number)).size).toBe(2);

    const again = await runBillingRenewalJob(now);
    expect(again.processed).toBe(0);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(2);

    const notes = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    expect(notes.items.filter((note) => note.kind === "invoice_issued")).toHaveLength(2);

    const adminNotes = await notificationRepo.listNotifications({
      orgId: tenant.org.id,
      recipientId: tenant.userIds.admin,
      unreadOnly: false,
      limit: 20,
      cursor: null,
    });
    expect(adminNotes.items.filter((note) => note.kind === "invoice_issued")).toHaveLength(0);

    const activity = await activityRepo.listActivity({
      orgId: tenant.org.id,
      action: ["billing.invoice_issued"],
      limit: 20,
      cursor: null,
    });
    expect(activity.items).toHaveLength(2);
    expect(activity.items[0]?.subjectKind).toBe("subscription");
    expect(activity.items[0]?.subjectId).toBe(tenant.org.id);
  });

  it("carries a clamped day forward across renewals", async () => {
    const tenant = await createTenant("renew-clamp", "starter");
    await shape(tenant.org.id, {
      status: "active",
      seats: 1,
      currentPeriodStart: iso(new Date("2026-01-31T15:30:00.000Z")),
      currentPeriodEnd: iso(new Date("2026-02-28T15:30:00.000Z")),
    });

    await runBillingRenewalJob(new Date("2026-03-28T15:29:00.000Z"));

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription?.currentPeriodStart).toBe("2026-02-28T15:30:00.000Z");
    expect(subscription?.currentPeriodEnd).toBe("2026-03-28T15:30:00.000Z");
    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]?.amountCents).toBe(900);
  });

  it("moves an annual period by a year and invoices twelve months", async () => {
    const tenant = await createTenant("renew-annual", "starter");
    await shape(tenant.org.id, {
      status: "active",
      interval: "annual",
      seats: 1,
      currentPeriodStart: iso(new Date("2024-02-29T08:15:00.000Z")),
      currentPeriodEnd: iso(new Date("2025-02-28T08:15:00.000Z")),
    });

    await runBillingRenewalJob(new Date("2025-02-28T08:15:00.000Z"));

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription?.currentPeriodStart).toBe("2025-02-28T08:15:00.000Z");
    expect(subscription?.currentPeriodEnd).toBe("2026-02-28T08:15:00.000Z");
    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]?.amountCents).toBe(900 * 12);
  });

  it("advances the free plan without invoices", async () => {
    const tenant = await createTenant("renew-free", "free");
    await shape(tenant.org.id, {
      status: "active",
      currentPeriodStart: iso(new Date("2026-01-01T00:00:00.000Z")),
      currentPeriodEnd: iso(new Date("2026-02-01T00:00:00.000Z")),
    });

    const result = await runBillingRenewalJob(new Date("2026-02-01T00:00:00.000Z"));
    expect(result.processed).toBe(1);
    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription?.plan).toBe("free");
    expect(subscription?.currentPeriodEnd).toBe("2026-03-01T00:00:00.000Z");
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
  });

  it("leaves trialing and past_due subscriptions alone", async () => {
    const trialing = await createTenant("renew-trial", "growth");
    const trialEnd = iso(new Date("2026-01-01T00:00:00.000Z"));
    await shape(trialing.org.id, { status: "trialing", currentPeriodEnd: trialEnd });

    const pastDue = await createTenant("renew-pastdue", "growth");
    await shape(pastDue.org.id, {
      status: "past_due",
      currentPeriodEnd: trialEnd,
    });

    await runBillingRenewalJob(new Date("2026-06-01T00:00:00.000Z"));

    expect((await subscriptionRepo.findSubscription(trialing.org.id))?.status).toBe("trialing");
    expect((await subscriptionRepo.findSubscription(trialing.org.id))?.currentPeriodEnd).toBe(
      trialEnd,
    );
    expect((await subscriptionRepo.findSubscription(pastDue.org.id))?.status).toBe("past_due");
    expect(await invoiceRepo.listInvoices(trialing.org.id)).toHaveLength(0);
    expect(await invoiceRepo.listInvoices(pastDue.org.id)).toHaveLength(0);
  });

  it("does nothing before the cancellation date, even if the period ended", async () => {
    const tenant = await createTenant("renew-cancel-future", "starter");
    const periodEnd = iso(new Date("2026-01-01T00:00:00.000Z"));
    const cancelAt = iso(new Date("2026-08-01T00:00:00.000Z"));
    await shape(tenant.org.id, {
      status: "canceled",
      currentPeriodEnd: periodEnd,
      cancelAt,
    });

    const result = await runBillingRenewalJob(new Date("2026-06-01T00:00:00.000Z"));
    expect(result.processed).toBe(0);
    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription?.status).toBe("canceled");
    expect(subscription?.plan).toBe("starter");
    expect(subscription?.currentPeriodEnd).toBe(periodEnd);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
  });

  it("ends a due cancellation on the free plan and catches the period up", async () => {
    const tenant = await createTenant("renew-cancel-due", "growth");
    const cancelAt = iso(new Date("2026-01-31T08:00:00.000Z"));
    await shape(tenant.org.id, {
      status: "canceled",
      interval: "annual",
      seats: 4,
      currentPeriodEnd: iso(new Date("2025-06-01T00:00:00.000Z")),
      cancelAt,
    });

    const events: Array<{ from: string; to: string; actorId: string | null }> = [];
    const off = subscribe("billing.plan_changed", (payload) => {
      if (payload.orgId === tenant.org.id) {
        events.push({ from: payload.from, to: payload.to, actorId: payload.actorId });
      }
    });

    const now = new Date("2026-03-10T08:00:00.000Z");
    await runBillingRenewalJob(now);
    const again = await runBillingRenewalJob(now);
    off();

    expect(again.processed).toBe(0);
    expect(events).toEqual([{ from: "growth", to: "free", actorId: null }]);

    const subscription = await subscriptionRepo.findSubscription(tenant.org.id);
    expect(subscription).toMatchObject({
      plan: "free",
      status: "active",
      interval: "monthly",
      cancelAt: null,
      currentPeriodStart: "2026-02-28T08:00:00.000Z",
      currentPeriodEnd: "2026-03-28T08:00:00.000Z",
    });
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
  });

