    const start = new Date(end.getTime() - 31 * DAY);

    const active = await createTenant("seats-active", "starter");
    await shape(active.org.id, {
      status: "active",
      seats: 2,
      interval: "monthly",
      currentPeriodStart: iso(start),
      currentPeriodEnd: iso(end),
    });

    await billingService.updateSeats(active.actors.owner, {
      orgId: active.org.id,
      seats: 4,
    });

    const invoices = await invoiceRepo.listInvoices(active.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]?.amountCents).toBe(Math.floor((900 * 2 * 15) / 31));
    expect(invoices[0]?.periodStart).toBe(iso(start));
    expect(invoices[0]?.periodEnd).toBe(iso(end));
    expect((await subscriptionRepo.findSubscription(active.org.id))?.seats).toBe(4);
    expect((await subscriptionRepo.findSubscription(active.org.id))?.currentPeriodEnd).toBe(iso(end));

    await billingService.updateSeats(active.actors.owner, {
      orgId: active.org.id,
      seats: 3,
    });
    expect(await invoiceRepo.listInvoices(active.org.id)).toHaveLength(1);

    const trialing = await createTenant("seats-trial", "starter");
    await billingService.updateSeats(trialing.actors.owner, {
      orgId: trialing.org.id,
      seats: 3,
    });
    expect(await invoiceRepo.listInvoices(trialing.org.id)).toHaveLength(0);

    const free = await createTenant("seats-free", "free");
    await billingService.updateSeats(free.actors.owner, {
      orgId: free.org.id,
      seats: 2,
    });
    expect(await invoiceRepo.listInvoices(free.org.id)).toHaveLength(0);
  });

  it("charges nothing once the period end has been reached", async () => {
    const active = await createTenant("seats-ended", "starter");
    await shape(active.org.id, {
      status: "active",
      seats: 1,
      currentPeriodStart: iso(new Date(Date.now() - 40 * 24 * 60 * 60 * 1000)),
      currentPeriodEnd: iso(new Date(Date.now() - 1000)),
    });

    await billingService.updateSeats(active.actors.owner, {
      orgId: active.org.id,
      seats: 3,
    });
    expect(await invoiceRepo.listInvoices(active.org.id)).toHaveLength(0);
    expect((await subscriptionRepo.findSubscription(active.org.id))?.seats).toBe(3);
  });

  it("prorates an upgrade, ignores a downgrade, and keeps the period", async () => {
    const DAY = 24 * 60 * 60 * 1000;
    const now = Date.now();
    const end = new Date(now + 14 * DAY + 22 * 60 * 60 * 1000);
    const start = new Date(end.getTime() - 31 * DAY);

    const tenant = await createTenant("plan-upgrade", "starter");
    await shape(tenant.org.id, {
      status: "active",
      seats: 2,
      interval: "monthly",
      currentPeriodStart: iso(start),
      currentPeriodEnd: iso(end),
    });

    const upgraded = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "annual",
    });
    expect(upgraded.currentPeriodStart).toBe(iso(start));
    expect(upgraded.currentPeriodEnd).toBe(iso(end));
    expect(upgraded.plan).toBe("growth");
    expect(upgraded.interval).toBe("annual");

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(1);
    // Difference uses the current monthly period, not the newly chosen annual interval.
    expect(invoices[0]?.amountCents).toBe(Math.floor(((1900 - 900) * 2 * 15) / 31));

    const downgraded = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "monthly",
    });
    expect(downgraded.currentPeriodEnd).toBe(iso(end));
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(1);
  });

  it("keeps a trial period and does not invoice a plan chosen during it", async () => {
    const tenant = await createTenant("plan-trial", "starter");
    const before = await subscriptionRepo.findSubscription(tenant.org.id);

    const changed = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "growth",
      interval: "annual",
    });

    expect(changed.status).toBe("active");
    expect(changed.plan).toBe("growth");
    expect(changed.currentPeriodStart).toBe(before?.currentPeriodStart);
    expect(changed.currentPeriodEnd).toBe(before?.currentPeriodEnd);
    expect(await invoiceRepo.listInvoices(tenant.org.id)).toHaveLength(0);
  });

  it("starts a full period when leaving the free plan", async () => {
    const tenant = await createTenant("plan-from-free", "free");
    const before = Date.now();
    const changed = await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "starter",
      interval: "annual",
    });
    const after = Date.now();

    expect(changed.plan).toBe("starter");
    expect(changed.interval).toBe("annual");
    expect(changed.status).toBe("active");
    const startMs = new Date(changed.currentPeriodStart).getTime();
    expect(startMs).toBeGreaterThanOrEqual(before);
    expect(startMs).toBeLessThanOrEqual(after);
    expect(changed.currentPeriodEnd).toBe(
      addCalendarMonths(new Date(changed.currentPeriodStart), 12).toISOString(),
    );

    const invoices = await invoiceRepo.listInvoices(tenant.org.id);
    expect(invoices).toHaveLength(1);
    expect(invoices[0]?.amountCents).toBe(900 * 12);
    expect(invoices[0]?.periodStart).toBe(changed.currentPeriodStart);
    expect(invoices[0]?.periodEnd).toBe(changed.currentPeriodEnd);
  });
});
